const HOURS_LIMIT = 72; // Aumentado para cobrir gaps de fim de semana
const historyItems = $input.all();
let formattedHistory = "";
const now = new Date();
const cutoffTime = new Date(now.getTime() - (HOURS_LIMIT * 60 * 60 * 1000));

if (historyItems.length > 0) {
    // Ordenar por data para garantir cronologia
    historyItems.sort((a, b) => new Date(a.json.created_at) - new Date(b.json.created_at));

    for (const item of historyItems) {
        const msgDateStr = item.json.created_at || item.json.timestamp;
        if (msgDateStr) {
            const msgDate = new Date(msgDateStr);
            if (msgDate > cutoffTime) {
                const role = item.json.role === 'human' ? 'Cliente' : 'SDR';
                const cleanContent = (item.json.content || "").replace(/\n/g, " ");
                formattedHistory += `${role}: ${cleanContent}\n`;
            }
        }
    }
}
return [{ json: { formattedHistory } }];

