const now = new Date();
const validLeads = [];

// Função que detecta o formato e converte corretamente
function parseMixedDate(dateStr) {
    if (!dateStr) return null;

    // 1. Tenta ler formato ISO do Supabase (ex: 2026-01-09 17:23:52...)
    // O JS entende isso nativamente se tiver hifens e T ou espaço
    if (dateStr.includes('-') && (dateStr.includes('T') || dateStr.includes(' '))) {
        return new Date(dateStr);
    }

    // 2. Tenta ler formato Brasileiro (ex: 23/01/2026 20:21)
    if (dateStr.includes('/')) {
        try {
            const [datePart, timePart] = dateStr.split(' ');
            const [day, month, year] = datePart.split('/');
            const [hour, minute] = timePart ? timePart.split(':') : [0, 0];

            // Mês em JS começa em 0
            return new Date(year, month - 1, day, hour, minute);
        } catch (e) {
            return null;
        }
    }

    return null;
}

for (const item of $input.all()) {
    const lastInteractionStr = $input.first().json.last_interaction_at;
    const stage = $input.first().json.followup_stage || 0;

    // Configuração dinâmica dos tempos (em horas)
    let hoursWait = 24; 

    if (stage === 0) {
        hoursWait = 0.5; // 30 minutos
    } else if (stage === 1) {
        hoursWait = 2;   // 2 horas
    } else if (stage === 2) {
        hoursWait = 23;  // 23 horas
    }

    if (lastInteractionStr) {
        const lastInteraction = parseMixedDate(lastInteractionStr);

        if (lastInteraction && !isNaN(lastInteraction.getTime())) {
            const diffInMs = now - lastInteraction;
            const diffInHours = diffInMs / (1000 * 60 * 60);

            // Verifica se já passou o tempo necessário
            if (diffInHours >= hoursWait) {
                // Adiciona infos para debug
                item.json.debug_hours_passed = diffInHours.toFixed(2);
                item.json.debug_hours_required = hoursWait;

                validLeads.push(item);
            }
        }
    }
}

return validLeads;

